static SymtableData function_data(Ctx* ctx,
                                  IrType return_type,
                                  size_t ir_index,
                                  size_t param_count) {
  SymtableData data = {
      .symbol_type = SYMBOL_FUNCTION,
      .ir_type = return_type,
      .ir_index = ir_index,
      .param_count = param_count,
      .param_types = NULL,
      .is_val = false,
  };
  if (param_count > 0)
    data.param_types = TRY_MALLOC(sizeof(IrType) * param_count);
  return data;
}

