// becomes a function symbol, its function id is its position among the
// PROGRAM's children. Afterwards checks @main: none is exit 3, more than one
// exit 4 (the Unit return type check comes with the return type ticket).
static void collect_functions(Ctx* ctx, Sema* sema) {
  size_t mains = 0;
  size_t count = ast_node_get_child_count(sema->program);
  for (size_t id = 0; id < count; id++) {
    AstNode* def = NULL;
    ast_node_get_child(ctx, sema->program, id, &def);
    if (ast_node_get_type(def) != AST_NODE_DEF)
      THROW(E_INTERNAL_ERROR, "unexpected top-level node at %d:%d",
            ast_node_get_line(def), ast_node_get_column(def));

    // AI generated by: Claude Code (claude-opus-5-5)
    // Prompt: "implementation done using skill:
    // mattpocock-skills:implement-spec, ticket 02: tracer, semantic entry
    // point, member entries and function collection"
    // Changes:
    // Review fix: a second @main is exit 4 even when it also has a parameter
    // (exit 5), so it is counted before the function is collected
    if (ast_node_get_flags(def) & (unsigned)AST_FLAG_MAIN) {
      mains++;
      if (mains > 1) {
        AstNode* ident = NULL;
        ast_node_get_child(ctx, def, AST_DEF_IDENT, &ident);
        THROW(E_SEMANTIC_REDEFINITION_ERROR,
              "more than one @main function, second one '%s' at %d:%d",
              ast_node_get_name(ident), ast_node_get_line(ident),
              ast_node_get_column(ident));
      }
    }

    collect_function(ctx, sema, def, id);
  }
  if (mains == 0)
    THROW(E_SEMANTIC_UNDEFINED_ERROR, "no @main function in the program");
}

